import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MCP Инструменты","description":"","frontmatter":{},"headers":[],"relativePath":"ru/mcp-tools/overview.md","filePath":"ru/mcp-tools/overview.md","lastUpdated":1784903584000}'),a={name:"ru/mcp-tools/overview.md"};function n(r,t,s,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="mcp-инструменты" tabindex="-1">MCP Инструменты <a class="header-anchor" href="#mcp-инструменты" aria-label="Permalink to &quot;MCP Инструменты&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp предоставляет <strong>19 MCP инструментов</strong>, которые дают LLM-агенту полный доступ к вашим API через протокол Model Context Protocol. Эти инструменты покрывают полный рабочий процесс: обнаружение доступных API, навигацию по иерархии спецификаций, поиск и проверку эндпоинтов, выполнение API-вызовов и работу с большими ответами.</p><h3 id="что-решают-инструменты" tabindex="-1">Что решают инструменты <a class="header-anchor" href="#что-решают-инструменты" aria-label="Permalink to &quot;Что решают инструменты&quot;">​</a></h3><ul><li><strong>Обнаружение</strong> — LLM может находить спецификации, коллекции и теги без предварительного знания ID</li><li><strong>Навигация</strong> — спуск от спецификации → коллекции → тега → эндпоинта по структурированной иерархии</li><li><strong>Поиск</strong> — полнотекстовый поиск по всем эндпоинтам, когда нет ID</li><li><strong>Проверка</strong> — получение полного объекта OpenAPI-операции перед вызовом</li><li><strong>Выполнение</strong> — выполнение реальных API-вызовов с автоматической аутентификацией</li><li><strong>Обработка больших ответов</strong> — обзор, сжатие и извлечение фрагментов ответов, которые не помещаются в строку</li></ul><h3 id="только-чтение-vs-изменяемые" tabindex="-1">Только чтение vs Изменяемые <a class="header-anchor" href="#только-чтение-vs-изменяемые" aria-label="Permalink to &quot;Только чтение vs Изменяемые&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Тип</th><th>Количество</th><th>Инструменты</th></tr></thead><tbody><tr><td><strong>Только чтение</strong></td><td>17</td><td>Все инструменты обнаружения, эндпоинтов, поиска, проверки, информации и ответов</td></tr><tr><td><strong>Изменяемые</strong></td><td>2</td><td><code>invoke</code> (выполняет реальные HTTP-вызовы), <code>auth</code> (получает токены)</td></tr></tbody></table><p>Инструменты только для чтения помечены флагами <code>ReadOnlyHint=true</code> и <code>IdempotentHint=true</code> в протоколе MCP, сообщая LLM, что их можно безопасно вызывать без побочных эффектов.</p><h3 id="обработка-ошибок" tabindex="-1">Обработка ошибок <a class="header-anchor" href="#обработка-ошибок" aria-label="Permalink to &quot;Обработка ошибок&quot;">​</a></h3><p>Все инструменты возвращают ошибки в виде структурированных объектов <code>LLMError</code> с машиночитаемым кодом и человекочитаемым сообщением, объясняющим, что пошло не так и что делать дальше:</p><table tabindex="0"><thead><tr><th>Код ошибки</th><th>Значение</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>Некорректный ввод (неверный формат ID, отсутствуют обязательные поля)</td></tr><tr><td><code>not_found</code></td><td>Сущность не найдена в индексе или рабочей области</td></tr><tr><td><code>rate_limit</code></td><td>Второй вызов <code>invoke</code> в течение 10 секунд на том же эндпоинте</td></tr><tr><td><code>invoke_error</code></td><td>Ошибка HTTP-вызова, ошибка загрузки</td></tr><tr><td><code>auth_error</code></td><td>Ошибка получения токена аутентификации</td></tr><tr><td><code>config_error</code></td><td>Ошибка загрузки или сохранения конфигурационного файла</td></tr><tr><td><code>parse_error</code></td><td>Ошибка парсинга файла спецификации</td></tr></tbody></table><h2 id="категории" tabindex="-1">Категории <a class="header-anchor" href="#категории" aria-label="Permalink to &quot;Категории&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Категория</th><th>Инструменты</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Обнаружение</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>Навигация по иерархии спецификаций: поиск спецификаций, коллекций и тегов</td></tr><tr><td><strong>Эндпоинты</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>Просмотр эндпоинтов на разных уровнях иерархии</td></tr><tr><td><strong>Выполнение</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>Поиск, проверка полного контракта и вызов API</td></tr><tr><td><strong>Утилиты</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>Токены аутентификации, информация о рантайме и обработка больших ответов</td></tr><tr><td><strong>Навыки</strong></td><td><a href="/mcp-tools/skills">Руководство по форматированию</a></td><td>Настройка отображения ответов инструментов</td></tr></tbody></table><h2 id="полныи-список" tabindex="-1">Полный список <a class="header-anchor" href="#полныи-список" aria-label="Permalink to &quot;Полный список&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Инструмент</th><th>Описание</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>Список всех спецификаций API в рабочей области</td></tr><tr><td><code>spec_by_id</code></td><td>Детальная информация о спецификации с коллекциями</td></tr><tr><td><code>collection_by_spec</code></td><td>Список коллекций в спецификации</td></tr><tr><td><code>collection_by_id</code></td><td>Детали коллекции с тегами</td></tr><tr><td><code>tag_by_spec</code></td><td>Список всех тегов в спецификации</td></tr><tr><td><code>tag_by_collection</code></td><td>Список тегов в коллекции</td></tr><tr><td><code>tag_by_id</code></td><td>Детали тега (ID, название, количество методов)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>Список всех эндпоинтов в спецификации</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Список эндпоинтов в коллекции</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Список эндпоинтов в теге</td></tr><tr><td><code>endpoint_by_id</code></td><td>Краткая сводка эндпоинта (метод, путь, описание)</td></tr><tr><td><code>search</code></td><td>Полнотекстовый поиск по всем эндпоинтам</td></tr><tr><td><code>inspect</code></td><td>Полные детали OpenAPI-операции (параметры, схемы)</td></tr><tr><td><code>invoke</code></td><td>Выполнение реального API-вызова</td></tr><tr><td><code>auth</code></td><td>Получение токена или заголовков аутентификации для спецификации</td></tr><tr><td><code>info</code></td><td>Информация о рантайме (версия, спецификации, конфиг)</td></tr><tr><td><code>response_outline</code></td><td>Структурная сводка большого файла ответа</td></tr><tr><td><code>response_compress</code></td><td>Сжатие большого ответа для встраивания в строку</td></tr><tr><td><code>response_slice</code></td><td>Извлечение фрагмента большого ответа</td></tr></tbody></table><h2 id="иерархия-навигации" tabindex="-1">Иерархия навигации <a class="header-anchor" href="#иерархия-навигации" aria-label="Permalink to &quot;Иерархия навигации&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>Когда у вас нет ID, используйте <code>search</code> для поиска эндпоинтов по запросу. Когда <code>invoke</code> возвращает <code>fileRef</code> (ответ слишком большой), используйте <code>response_outline</code> → <code>response_compress</code> или <code>response_slice</code> для изучения данных.</p>`,18)])])}const b=d(a,[["render",n]]);export{h as __pageData,b as default};
